31	class MappingConfig {
32	
33	  MappingConfig() {
34	    BoolEnvar ForceAtomic = BoolEnvar("LIBOMPTARGET_MAP_FORCE_ATOMIC", true);
35	    UseEventsForAtomicTransfers = ForceAtomic;
36	
37	    BoolEnvar TreatAttachAutoAsAlwaysEnvar(
38	        "LIBOMPTARGET_TREAT_ATTACH_AUTO_AS_ALWAYS", false);
39	    TreatAttachAutoAsAlways = TreatAttachAutoAsAlwaysEnvar;
40	  }
41	
42	public:
43	  static const MappingConfig &get() {
44	    static MappingConfig MP;
45	    return MP;
46	  };
47	
48	  /// Flag to indicate if we use events to ensure the atomicity of
49	  /// map clauses or not. Can be modified with an environment variable.
50	  bool UseEventsForAtomicTransfers = true;
51	
52	  /// Flag to indicate if attach(auto) should be treated as attach(always).
53	  /// This forces pointer attachments to occur between a pointer an a pointee,
54	  /// for something like `map(p[:])` even when both were already present on the
55	  /// device before encountering the construct. Can be modified with
56	  /// an environment variable.
57	  bool TreatAttachAutoAsAlways = false;
58	};
59	
60	/// Information about shadow pointers.
61	struct ShadowPtrInfoTy {
62	  void **HstPtrAddr = nullptr;
63	  void **TgtPtrAddr = nullptr;
64	  int64_t PtrSize = sizeof(void *); // Size of the pointer/descriptor
65	
66	  // Store the complete contents for both host and target pointers/descriptors.
67	  // 96 bytes is chosen as the "Small" size to cover simple Fortran
68	  // descriptors of up to 3 dimensions.
69	  llvm::SmallVector<char, 96> HstPtrContent;
70	  llvm::SmallVector<char, 96> TgtPtrContent;
71	
72	  ShadowPtrInfoTy(void **HstPtrAddr, void **TgtPtrAddr, void *TgtPteeBase,
73	                  int64_t PtrSize)
74	      : HstPtrAddr(HstPtrAddr), TgtPtrAddr(TgtPtrAddr), PtrSize(PtrSize),
75	        HstPtrContent(PtrSize), TgtPtrContent(PtrSize) {
76	    constexpr int64_t VoidPtrSize = sizeof(void *);
77	    assert(HstPtrAddr != nullptr && "HstPtrAddr is nullptr");
78	    assert(TgtPtrAddr != nullptr && "TgtPtrAddr is nullptr");
79	    assert(PtrSize >= VoidPtrSize && "PtrSize is less than sizeof(void *)");
80	
81	    void *HstPteeBase = *HstPtrAddr;
82	    // The first VoidPtrSize bytes for HstPtrContent/TgtPtrContent are from
83	    // HstPteeBase/TgtPteeBase.
84	    std::memcpy(HstPtrContent.data(), &HstPteeBase, VoidPtrSize);
85	    std::memcpy(TgtPtrContent.data(), &TgtPteeBase, VoidPtrSize);
86	
87	    // If we are not dealing with Fortran descriptors (pointers larger than
88	    // VoidPtrSize), then that's that.
89	    if (PtrSize <= VoidPtrSize)
90	      return;
91	
92	    // For larger pointers, i.e. Fortran descriptors, the remaining contents of
93	    // the descriptor come from the host descriptor, i.e. HstPtrAddr.
94	    std::memcpy(HstPtrContent.data() + VoidPtrSize,
95	                reinterpret_cast<char *>(HstPtrAddr) + VoidPtrSize,
96	                PtrSize - VoidPtrSize);
97	    std::memcpy(TgtPtrContent.data() + VoidPtrSize,
98	                reinterpret_cast<char *>(HstPtrAddr) + VoidPtrSize,
99	                PtrSize - VoidPtrSize);
100	  }
101	
102	  ShadowPtrInfoTy() = delete;
103	
104	  bool operator==(const ShadowPtrInfoTy &Other) const {
105	    return HstPtrAddr == Other.HstPtrAddr;
106	  }
107	};
108	
109	inline bool operator<(const ShadowPtrInfoTy &lhs, const ShadowPtrInfoTy &rhs) {
110	  return lhs.HstPtrAddr < rhs.HstPtrAddr;
111	}
112	
113	/// Map between host data and target data.
114	struct HostDataToTargetTy {
115	  const uintptr_t HstPtrBase; // host info.
116	  const uintptr_t HstPtrBegin;
117	  const uintptr_t HstPtrEnd;       // non-inclusive.
118	  const map_var_info_t HstPtrName; // Optional source name of mapped variable.
119	
120	  const uintptr_t TgtAllocBegin; // allocated target memory
121	  const uintptr_t TgtPtrBegin; // mapped target memory = TgtAllocBegin + padding
122	
123	private:
124	  static const uint64_t INFRefCount = ~(uint64_t)0;
125	  static std::string refCountToStr(uint64_t RefCount) {
126	    return RefCount == INFRefCount ? "INF" : std::to_string(RefCount);
127	  }
128	
129	  struct StatesTy {
130	    StatesTy(uint64_t DRC, uint64_t HRC)
131	        : DynRefCount(DRC), HoldRefCount(HRC) {}
132	    /// The dynamic reference count is the standard reference count as of OpenMP
133	    /// 4.5.  The hold reference count is an OpenMP extension for the sake of
134	    /// OpenACC support.
135	    ///
136	    /// The 'ompx_hold' map type modifier is permitted only on "omp target" and
137	    /// "omp target data", and "delete" is permitted only on "omp target exit
138	    /// data" and associated runtime library routines.  As a result, we really
139	    /// need to implement "reset" functionality only for the dynamic reference
140	    /// counter.  Likewise, only the dynamic reference count can be infinite
141	    /// because, for example, omp_target_associate_ptr and "omp declare target
142	    /// link" operate only on it.  Nevertheless, it's actually easier to follow
143	    /// the code (and requires less assertions for special cases) when we just
144	    /// implement these features generally across both reference counters here.
145	    /// Thus, it's the users of this class that impose those restrictions.
146	    ///
147	    uint64_t DynRefCount;
148	    uint64_t HoldRefCount;
149	
150	    /// A map of shadow pointers associated with this entry, the keys are host
151	    /// pointer addresses to identify stale entries.
152	    llvm::SmallSet<ShadowPtrInfoTy, 2> ShadowPtrInfos;
153	
154	    /// Pointer to the event corresponding to the data update of this map.
155	    /// Note: At present this event is created when the first data transfer from
156	    /// host to device is issued, and only being used for H2D. It is not used
157	    /// for data transfer in another direction (device to host). It is still
158	    /// unclear whether we need it for D2H. If in the future we need similar
159	    /// mechanism for D2H, and if the event cannot be shared between them, Event
160	    /// should be written as <tt>void *Event[2]</tt>.
161	    void *Event = nullptr;
162	
163	    /// Number of threads currently holding a reference to the entry at a
164	    /// targetDataEnd. This is used to ensure that only the last thread that
165	    /// references this entry will actually delete it.
166	    int32_t DataEndThreadCount = 0;
167	  };
168	  // When HostDataToTargetTy is used by std::set, std::set::iterator is const
169	  // use unique_ptr to make States mutable.
170	  const std::unique_ptr<StatesTy> States;
171	
172	public:
173	  HostDataToTargetTy(uintptr_t BP, uintptr_t B, uintptr_t E,
174	                     uintptr_t TgtAllocBegin, uintptr_t TgtPtrBegin,
175	                     bool UseHoldRefCount, map_var_info_t Name = nullptr,
176	                     bool IsINF = false)
177	      : HstPtrBase(BP), HstPtrBegin(B), HstPtrEnd(E), HstPtrName(Name),
178	        TgtAllocBegin(TgtAllocBegin), TgtPtrBegin(TgtPtrBegin),
179	        States(std::make_unique<StatesTy>(UseHoldRefCount ? 0
180	                                          : IsINF         ? INFRefCount
181	                                                          : 1,
182	                                          !UseHoldRefCount ? 0
183	                                          : IsINF          ? INFRefCount
184	                                                           : 1)) {}
185	
186	  /// Get the total reference count.  This is smarter than just getDynRefCount()
187	  /// + getHoldRefCount() because it handles the case where at least one is
188	  /// infinity and the other is non-zero.
189	  uint64_t getTotalRefCount() const {
190	    if (States->DynRefCount == INFRefCount ||
191	        States->HoldRefCount == INFRefCount)
192	      return INFRefCount;
193	    return States->DynRefCount + States->HoldRefCount;
194	  }
195	
196	  /// Get the dynamic reference count.
197	  uint64_t getDynRefCount() const { return States->DynRefCount; }
198	
199	  /// Get the hold reference count.
200	  uint64_t getHoldRefCount() const { return States->HoldRefCount; }
201	
202	  /// Get the event bound to this data map.
203	  void *getEvent() const { return States->Event; }
204	
205	  /// Add a new event, if necessary.
206	  /// Returns OFFLOAD_FAIL if something went wrong, OFFLOAD_SUCCESS otherwise.
207	  int addEventIfNecessary(DeviceTy &Device, AsyncInfoTy &AsyncInfo) const;
208	
209	  /// Functions that manages the number of threads referencing the entry in a
210	  /// targetDataEnd.
211	  void incDataEndThreadCount() { ++States->DataEndThreadCount; }
212	
213	  [[nodiscard]] int32_t decDataEndThreadCount() {
214	    return --States->DataEndThreadCount;
215	  }
216	
217	  [[nodiscard]] int32_t getDataEndThreadCount() const {
218	    return States->DataEndThreadCount;
219	  }
220	
221	  /// Set the event bound to this data map.
222	  void setEvent(void *Event) const { States->Event = Event; }
223	
224	  /// Reset the specified reference count unless it's infinity.  Reset to 1
225	  /// (even if currently 0) so it can be followed by a decrement.
226	  void resetRefCount(bool UseHoldRefCount) const {
227	    uint64_t &ThisRefCount =
228	        UseHoldRefCount ? States->HoldRefCount : States->DynRefCount;
229	    if (ThisRefCount != INFRefCount)
230	      ThisRefCount = 1;
231	  }
232	
233	  /// Increment the specified reference count unless it's infinity.
234	  void incRefCount(bool UseHoldRefCount) const {
235	    uint64_t &ThisRefCount =
236	        UseHoldRefCount ? States->HoldRefCount : States->DynRefCount;
237	    if (ThisRefCount != INFRefCount) {
238	      ++ThisRefCount;
239	      assert(ThisRefCount < INFRefCount && "refcount overflow");
240	    }
241	  }
242	
243	  /// Decrement the specified reference count unless it's infinity or zero, and
244	  /// return the total reference count.
245	  uint64_t decRefCount(bool UseHoldRefCount) const {
246	    uint64_t &ThisRefCount =
247	        UseHoldRefCount ? States->HoldRefCount : States->DynRefCount;
248	    uint64_t OtherRefCount =
249	        UseHoldRefCount ? States->DynRefCount : States->HoldRefCount;
250	    (void)OtherRefCount;
251	    if (ThisRefCount != INFRefCount) {
252	      if (ThisRefCount > 0)
253	        --ThisRefCount;
254	      else
255	        assert(OtherRefCount >= 0 && "total refcount underflow");
256	    }
257	    return getTotalRefCount();
258	  }
259	
260	  /// Is the dynamic (and thus the total) reference count infinite?
261	  bool isDynRefCountInf() const { return States->DynRefCount == INFRefCount; }
262	
263	  /// Convert the dynamic reference count to a debug string.
264	  std::string dynRefCountToStr() const {
265	    return refCountToStr(States->DynRefCount);
266	  }
267	
268	  /// Convert the hold reference count to a debug string.
269	  std::string holdRefCountToStr() const {
270	    return refCountToStr(States->HoldRefCount);
271	  }
272	
273	  /// Should one decrement of the specified reference count (after resetting it
274	  /// if \c AfterReset) remove this mapping?
275	  bool decShouldRemove(bool UseHoldRefCount, bool AfterReset = false) const {
276	    uint64_t ThisRefCount =
277	        UseHoldRefCount ? States->HoldRefCount : States->DynRefCount;
278	    uint64_t OtherRefCount =
279	        UseHoldRefCount ? States->DynRefCount : States->HoldRefCount;
280	    if (OtherRefCount > 0)
281	      return false;
282	    if (AfterReset)
283	      return ThisRefCount != INFRefCount;
284	    return ThisRefCount == 1;
285	  }
286	
287	  /// Add the shadow pointer info \p ShadowPtrInfo to this entry but only if the
288	  /// the target ptr value was not already present in the existing set of shadow
289	  /// pointers. Return true if something was added.
290	  bool addShadowPointer(const ShadowPtrInfoTy &ShadowPtrInfo) const {
291	    auto Pair = States->ShadowPtrInfos.insert(ShadowPtrInfo);
292	    if (Pair.second)
293	      return true;
294	
295	    // Check for a stale entry, if found, replace the old one.
296	
297	    // For Fortran descriptors, we need to compare their full contents,
298	    // as the starting address may be the same while other fields have
299	    // been updated. e.g.
300	    //
301	    //   !$omp target enter data map(x(1:100)) !             (1)
302	    //   p => x(10: 19)
303	    //   !$omp target enter data map(p, p(:)) !              (2)
304	    //   p => x(5: 9)
305	    //   !$omp target enter data map(attach(always): p(:)) ! (3)
306	    //
307	    // While &desc_p and &p(1) (TgtPtrAddr and first "sizeof(void*)" bytes of
308	    // TgtPtrContent) are same for (2) and (3), the pointer attachment for (3)
309	    // needs to update the bounds information in the descriptor of p on device.
310	    if ((*Pair.first).TgtPtrContent == ShadowPtrInfo.TgtPtrContent)
311	      return false;
312	
313	    States->ShadowPtrInfos.erase(ShadowPtrInfo);
314	    return addShadowPointer(ShadowPtrInfo);
315	  }
316	
317	  /// Apply \p CB to all shadow pointers of this entry. Returns OFFLOAD_FAIL if
318	  /// \p CB returned OFFLOAD_FAIL for any of them, otherwise this returns
319	  /// OFFLOAD_SUCCESS. The entry is locked for this operation.
320	  template <typename CBTy> int foreachShadowPointerInfo(CBTy CB) const {
321	    for (auto &It : States->ShadowPtrInfos)
322	      if (CB(const_cast<ShadowPtrInfoTy &>(It)) == OFFLOAD_FAIL)
323	        return OFFLOAD_FAIL;
324	    return OFFLOAD_SUCCESS;
325	  }
326	
327	  /// Lock this entry for exclusive access. Ensure to get exclusive access to
328	  /// HDTTMap first!
329	  void lock() const { Mtx.lock(); }
330	
331	  /// Unlock this entry to allow other threads inspecting it.
332	  void unlock() const { Mtx.unlock(); }
333	
334	private:
335	  // Mutex that needs to be held before the entry is inspected or modified. The
336	  // HDTTMap mutex needs to be held before trying to lock any HDTT Entry.
337	  mutable std::mutex Mtx;
338	};
339	
340	/// Wrapper around the HostDataToTargetTy to be used in the HDTT map. In
341	/// addition to the HDTT pointer we store the key value explicitly. This
342	/// allows the set to inspect (sort/search/...) this entry without an additional
343	/// load of HDTT. HDTT is a pointer to allow the modification of the set without
344	/// invalidating HDTT entries which can now be inspected at the same time.
345	struct HostDataToTargetMapKeyTy {
346	  uintptr_t KeyValue;
347	
348	  HostDataToTargetMapKeyTy(void *Key) : KeyValue(uintptr_t(Key)) {}
349	  HostDataToTargetMapKeyTy(uintptr_t Key) : KeyValue(Key) {}
350	  HostDataToTargetMapKeyTy(HostDataToTargetTy *HDTT)
351	      : KeyValue(HDTT->HstPtrBegin), HDTT(HDTT) {}
352	  HostDataToTargetTy *HDTT;
353	};
354	inline bool operator<(const HostDataToTargetMapKeyTy &LHS,
355	                      const uintptr_t &RHS) {
356	  return LHS.KeyValue < RHS;
357	}
358	inline bool operator<(const uintptr_t &LHS,
359	                      const HostDataToTargetMapKeyTy &RHS) {
360	  return LHS < RHS.KeyValue;
361	}
362	inline bool operator<(const HostDataToTargetMapKeyTy &LHS,
363	                      const HostDataToTargetMapKeyTy &RHS) {
364	  return LHS.KeyValue < RHS.KeyValue;
365	}
366	
367	/// This struct will be returned by \p DeviceTy::getTargetPointer which provides
368	/// more data than just a target pointer. A TargetPointerResultTy that has a non
369	/// null Entry owns the entry. As long as the TargetPointerResultTy (TPR) exists
370	/// the entry is locked. To give up ownership without destroying the TPR use the
371	/// reset() function.
372	struct TargetPointerResultTy {
373	  struct FlagTy {
374	    /// If the map table entry is just created
375	    unsigned IsNewEntry : 1;
376	    /// If the pointer is actually a host pointer (when unified memory enabled)
377	    unsigned IsHostPointer : 1;
378	    /// If the pointer is present in the mapping table.
379	    unsigned IsPresent : 1;
380	    /// Flag indicating that this was the last user of the entry and the ref
381	    /// count is now 0.
382	    unsigned IsLast : 1;
383	    /// If the pointer is contained.
384	    unsigned IsContained : 1;
385	  } Flags = {0, 0, 0, 0, 0};
386	
387	  TargetPointerResultTy(const TargetPointerResultTy &) = delete;
388	  TargetPointerResultTy &operator=(const TargetPointerResultTy &TPR) = delete;
389	  TargetPointerResultTy() {}
390	
391	  TargetPointerResultTy(FlagTy Flags, HostDataToTargetTy *Entry,
392	                        void *TargetPointer)
393	      : Flags(Flags), TargetPointer(TargetPointer), Entry(Entry) {
394	    if (Entry)
395	      Entry->lock();
396	  }
397	
398	  TargetPointerResultTy(TargetPointerResultTy &&TPR)
399	      : Flags(TPR.Flags), TargetPointer(TPR.TargetPointer), Entry(TPR.Entry) {
400	    TPR.Entry = nullptr;
401	  }
402	
403	  TargetPointerResultTy &operator=(TargetPointerResultTy &&TPR) {
404	    if (&TPR != this) {
405	      std::swap(Flags, TPR.Flags);
406	      std::swap(Entry, TPR.Entry);
407	      std::swap(TargetPointer, TPR.TargetPointer);
408	    }
409	    return *this;
410	  }
411	
412	  ~TargetPointerResultTy() {
413	    if (Entry)
414	      Entry->unlock();
415	  }
416	
417	  bool isPresent() const { return Flags.IsPresent; }
418	
419	  bool isHostPointer() const { return Flags.IsHostPointer; }
420	
421	  bool isContained() const { return Flags.IsContained; }
422	
423	  /// The corresponding target pointer
424	  void *TargetPointer = nullptr;
425	
426	  HostDataToTargetTy *getEntry() const { return Entry; }
427	  void setEntry(HostDataToTargetTy *HDTTT,
428	                HostDataToTargetTy *OwnedTPR = nullptr) {
429	    if (Entry)
430	      Entry->unlock();
431	    Entry = HDTTT;
432	    if (Entry && Entry != OwnedTPR)
433	      Entry->lock();
434	  }
435	
436	  void reset() { *this = TargetPointerResultTy(); }
437	
438	private:
439	  /// The corresponding map table entry which is stable.
440	  HostDataToTargetTy *Entry = nullptr;
441	};
442	
443	struct LookupResult {
444	  struct {
445	    unsigned IsContained : 1;
446	    unsigned ExtendsBefore : 1;
447	    unsigned ExtendsAfter : 1;
448	  } Flags;
449	
450	  LookupResult() : Flags({0, 0, 0}), TPR() {}
451	
452	  TargetPointerResultTy TPR;
453	};
