455	// This structure stores information of a mapped memory region.
456	struct MapComponentInfoTy {
457	  void *Base;
458	  void *Begin;
459	  int64_t Size;
460	  int64_t Type;
461	  void *Name;
462	  MapComponentInfoTy() = default;
463	  MapComponentInfoTy(void *Base, void *Begin, int64_t Size, int64_t Type,
464	                     void *Name)
465	      : Base(Base), Begin(Begin), Size(Size), Type(Type), Name(Name) {}
466	};
