468	// This structure stores all components of a user-defined mapper. The number of
469	// components are dynamically decided, so we utilize C++ STL vector
470	// implementation here.
471	struct MapperComponentsTy {
472	  llvm::SmallVector<MapComponentInfoTy> Components;
473	  int32_t size() { return Components.size(); }
474	};
