476	// The mapper function pointer type. It follows the signature below:
477	// void .omp_mapper.<type_name>.<mapper_id>.(void *rt_mapper_handle,
478	//                                           void *base, void *begin,
479	//                                           size_t size, int64_t type,
480	//                                           void * name);
481	typedef void (*MapperFuncPtrTy)(void *, void *, void *, int64_t, int64_t,
482	                                void *);
