484	/// Structure to store information about a single ATTACH map entry.
485	struct AttachMapInfo {
486	  void *PointerBase;
487	  void *PointeeBegin;
488	  int64_t PointerSize;
489	  int64_t MapType;
490	  map_var_info_t Pointername;
491	
492	  AttachMapInfo(void *PointerBase, void *PointeeBegin, int64_t Size,
493	                int64_t Type, map_var_info_t Name)
494	      : PointerBase(PointerBase), PointeeBegin(PointeeBegin), PointerSize(Size),
495	        MapType(Type), Pointername(Name) {}
496	};
497	
498	/// Structure to track new allocations, ATTACH entries, DELETE entries and
499	/// skipped FROM data transfer information for a given construct, across
500	/// recursive calls (for handling mappers) to targetDataBegin/targetDataEnd.
501	struct StateInfoTy {
502	  /// ATTACH map entries for deferred processing until all other maps are done.
503	  llvm::SmallVector<AttachMapInfo> AttachEntries;
504	
505	  /// Host pointers for which new memory was allocated.
506	  /// Key: host pointer, Value: allocation size.
507	  llvm::DenseMap<void *, int64_t> NewAllocations;
508	
509	  /// Host pointers that had a FROM entry, but for which a data transfer was
510	  /// skipped due to the ref-count not being zero.
511	  /// Key: host pointer, Value: data size.
512	  llvm::DenseMap<void *, int64_t> SkippedFromEntries;
513	
514	  /// Host pointers for which we have triggered a FROM transfer at some point
515	  /// during targetDataEnd. It's used to avoid duplicate transfers.
516	  /// Key: host pointer, Value: transferred size.
517	  llvm::DenseMap<void *, int64_t> TransferredFromEntries;
518	
519	  /// Starting host address and size of entries whose ref-count went to zero.
520	  /// This includes entries released through explicit DELETE, or normal
521	  /// ref-count decrements. It's used to ensure transfers are performed for FROM
522	  /// entries whose ref-count is already zero when the entry is encountered.
523	  /// Key: host pointer, Value: size.
524	  llvm::DenseMap<void *, int64_t> ReleasedEntries;
525	
526	  StateInfoTy() = default;
527	
528	  // Delete copy constructor and copy assignment operator to prevent copying
529	  StateInfoTy(const StateInfoTy &) = delete;
530	  StateInfoTy &operator=(const StateInfoTy &) = delete;
531	
532	private:
533	  /// Helper to find an entry in \p EntryMap that contains the pointer.
534	  /// Returns the matching entry if found, otherwise std::nullopt.
535	  std::optional<std::pair<void *, int64_t>>
536	  findEntryForPtr(void *Ptr,
537	                  const llvm::DenseMap<void *, int64_t> &EntryMap) const {
538	    for (const auto &Entry : EntryMap) {
539	      void *EntryBegin = Entry.first;
540	      int64_t EntrySize = Entry.second;
541	      if (Ptr >= EntryBegin &&
542	          Ptr < static_cast<void *>(static_cast<char *>(EntryBegin) +
543	                                    EntrySize)) {
544	        return Entry;
545	      }
546	    }
547	    return std::nullopt;
548	  }
549	
550	public:
551	  /// Check if a pointer falls within any of the newly allocated ranges.
552	  /// Returns the matching entry if found, otherwise std::nullopt.
553	  std::optional<std::pair<void *, int64_t>> wasNewlyAllocated(void *Ptr) const {
554	    return findEntryForPtr(Ptr, NewAllocations);
555	  }
556	
557	  /// Check if a pointer range [Ptr, Ptr+Size) is fully contained within any
558	  /// previously completed FROM transfer.
559	  /// Returns the matching entry if found, otherwise std::nullopt.
560	  std::optional<std::pair<void *, int64_t>>
561	  wasTransferredFrom(void *Ptr, int64_t Size) const {
562	    uintptr_t CheckBegin = reinterpret_cast<uintptr_t>(Ptr);
563	    uintptr_t CheckEnd = CheckBegin + Size;
564	
565	    for (const auto &Entry : TransferredFromEntries) {
566	      void *RangePtr = Entry.first;
567	      int64_t RangeSize = Entry.second;
568	      uintptr_t RangeBegin = reinterpret_cast<uintptr_t>(RangePtr);
569	      uintptr_t RangeEnd = RangeBegin + RangeSize;
570	
571	      if (CheckBegin >= RangeBegin && CheckEnd <= RangeEnd) {
572	        return Entry;
573	      }
574	    }
575	    return std::nullopt;
576	  }
577	
578	  /// Check if a pointer falls within any released entry's range.
579	  /// Returns the matching entry if found, otherwise std::nullopt.
580	  std::optional<std::pair<void *, int64_t>>
581	  wasPreviouslyReleased(void *Ptr) const {
582	    return findEntryForPtr(Ptr, ReleasedEntries);
583	  }
584	
585	  /// Add a skipped FROM entry. Only updates the entry if this is a new pointer
586	  /// or if the new size is larger than the existing entry.
587	  void addSkippedFromEntry(void *Ptr, int64_t Size) {
588	    auto It = SkippedFromEntries.find(Ptr);
589	    if (It == SkippedFromEntries.end() || Size > It->second) {
590	      SkippedFromEntries[Ptr] = Size;
591	    }
592	  }
593	
594	  /// Add a transferred FROM entry. Only updates the entry if this is a new
595	  /// pointer or if the new size is larger than the existing entry.
596	  void addTransferredFromEntry(void *Ptr, int64_t Size) {
597	    auto It = TransferredFromEntries.find(Ptr);
598	    if (It == TransferredFromEntries.end() || Size > It->second) {
599	      TransferredFromEntries[Ptr] = Size;
600	    }
601	  }
602	};
603	
604	// Function pointer type for targetData* functions (targetDataBegin,
605	// targetDataEnd and targetDataUpdate).
606	typedef int (*TargetDataFuncPtrTy)(ident_t *, DeviceTy &, int32_t, void **,
607	                                   void **, int64_t *, int64_t *,
608	                                   map_var_info_t *, void **, AsyncInfoTy &,
609	                                   StateInfoTy *, bool);
610	
611	void dumpTargetPointerMappings(const ident_t *Loc, DeviceTy &Device,
612	                               bool toStdOut = false);
613	
614	int targetDataBegin(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
615	                    void **ArgsBase, void **Args, int64_t *ArgSizes,
616	                    int64_t *ArgTypes, map_var_info_t *ArgNames,
617	                    void **ArgMappers, AsyncInfoTy &AsyncInfo,
618	                    StateInfoTy *StateInfo = nullptr, bool FromMapper = false);
619	
620	int targetDataEnd(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
621	                  void **ArgBases, void **Args, int64_t *ArgSizes,
622	                  int64_t *ArgTypes, map_var_info_t *ArgNames,
623	                  void **ArgMappers, AsyncInfoTy &AsyncInfo,
624	                  StateInfoTy *StateInfo = nullptr, bool FromMapper = false);
625	
626	int targetDataUpdate(ident_t *Loc, DeviceTy &Device, int32_t ArgNum,
627	                     void **ArgsBase, void **Args, int64_t *ArgSizes,
628	                     int64_t *ArgTypes, map_var_info_t *ArgNames,
629	                     void **ArgMappers, AsyncInfoTy &AsyncInfo,
630	                     StateInfoTy *StateInfo = nullptr, bool FromMapper = false);
631	
632	// Process deferred ATTACH map entries collected during targetDataBegin.
633	int processAttachEntries(DeviceTy &Device, StateInfoTy &StateInfo,
634	                         AsyncInfoTy &AsyncInfo);
635	
636	struct MappingInfoTy {
637	  MappingInfoTy(DeviceTy &Device) : Device(Device) {}
638	
639	  /// Host data to device map type with a wrapper key indirection that allows
640	  /// concurrent modification of the entries without invalidating the underlying
641	  /// entries.
642	  using HostDataToTargetListTy =
643	      std::set<HostDataToTargetMapKeyTy, std::less<>>;
644	
645	  /// The HDTTMap is a protected object that can only be accessed by one thread
646	  /// at a time.
647	  ProtectedObj<HostDataToTargetListTy> HostDataToTargetMap;
648	
649	  /// The type used to access the HDTT map.
650	  using HDTTMapAccessorTy = decltype(HostDataToTargetMap)::AccessorTy;
651	
652	  /// Lookup the mapping of \p HstPtrBegin in \p HDTTMap. The accessor ensures
653	  /// exclusive access to the HDTT map.
654	  LookupResult lookupMapping(HDTTMapAccessorTy &HDTTMap, void *HstPtrBegin,
655	                             int64_t Size,
656	                             HostDataToTargetTy *OwnedTPR = nullptr);
657	
658	  /// Get the target pointer based on host pointer begin and base. If the
659	  /// mapping already exists, the target pointer will be returned directly. In
660	  /// addition, if required, the memory region pointed by \p HstPtrBegin of size
661	  /// \p Size will also be transferred to the device. If the mapping doesn't
662	  /// exist, and if unified shared memory is not enabled, a new mapping will be
663	  /// created and the data will also be transferred accordingly. nullptr will be
664	  /// returned because of any of following reasons:
665	  /// - Data allocation failed;
666	  /// - The user tried to do an illegal mapping;
667	  /// - Data transfer issue fails.
668	  TargetPointerResultTy getTargetPointer(
669	      HDTTMapAccessorTy &HDTTMap, void *HstPtrBegin, void *HstPtrBase,
670	      int64_t TgtPadding, int64_t Size, map_var_info_t HstPtrName,
671	      bool HasFlagTo, bool HasFlagAlways, bool IsImplicit, bool UpdateRefCount,
672	      bool HasCloseModifier, bool HasPresentModifier, bool HasHoldModifier,
673	      AsyncInfoTy &AsyncInfo, HostDataToTargetTy *OwnedTPR = nullptr,
674	      bool ReleaseHDTTMap = true, StateInfoTy *StateInfo = nullptr);
675	
676	  /// Return the target pointer for \p HstPtrBegin in \p HDTTMap. The accessor
677	  /// ensures exclusive access to the HDTT map.
678	  void *getTgtPtrBegin(HDTTMapAccessorTy &HDTTMap, void *HstPtrBegin,
679	                       int64_t Size);
680	
681	  /// Return the target pointer begin (where the data will be moved).
682	  /// Used by targetDataBegin, targetDataEnd, targetDataUpdate and target.
683	  /// - \p UpdateRefCount and \p UseHoldRefCount controls which and if the entry
684	  /// reference counters will be decremented.
685	  /// - \p MustContain enforces that the query must not extend beyond an already
686	  /// mapped entry to be valid.
687	  /// - \p ForceDelete deletes the entry regardless of its reference counting
688	  /// (unless it is infinite).
689	  /// - \p FromDataEnd tracks the number of threads referencing the entry at
690	  /// targetDataEnd for delayed deletion purpose.
691	  [[nodiscard]] TargetPointerResultTy
692	  getTgtPtrBegin(void *HstPtrBegin, int64_t Size, bool UpdateRefCount,
693	                 bool UseHoldRefCount, bool MustContain = false,
694	                 bool ForceDelete = false, bool FromDataEnd = false);
695	
696	  /// Remove the \p Entry from the data map. Expect the entry's total reference
697	  /// count to be zero and the caller thread to be the last one using it. \p
698	  /// HDTTMap ensure the caller holds exclusive access and can modify the map.
699	  /// Return \c OFFLOAD_SUCCESS if the map entry existed, and return \c
700	  /// OFFLOAD_FAIL if not. It is the caller's responsibility to skip calling
701	  /// this function if the map entry is not expected to exist because \p
702	  /// HstPtrBegin uses shared memory.
703	  [[nodiscard]] int eraseMapEntry(HDTTMapAccessorTy &HDTTMap,
704	                                  HostDataToTargetTy *Entry, int64_t Size);
705	
706	  /// Deallocate the \p Entry from the device memory and delete it. Return \c
707	  /// OFFLOAD_SUCCESS if the deallocation operations executed successfully, and
708	  /// return \c OFFLOAD_FAIL otherwise.
709	  [[nodiscard]] int deallocTgtPtrAndEntry(HostDataToTargetTy *Entry,
710	                                          int64_t Size);
711	
712	  int associatePtr(void *HstPtrBegin, void *TgtPtrBegin, int64_t Size);
713	  int disassociatePtr(void *HstPtrBegin);
714	
715	  /// Print information about the transfer from \p HstPtr to \p TgtPtr (or vice
716	  /// versa if \p H2D is false). If there is an existing mapping, or if \p Entry
717	  /// is set, the associated metadata will be printed as well.
718	  void printCopyInfo(void *TgtPtr, void *HstPtr, int64_t Size, bool H2D,
719	                     HostDataToTargetTy *Entry,
720	                     MappingInfoTy::HDTTMapAccessorTy *HDTTMapPtr);
721	
722	private:
723	  DeviceTy &Device;
724	};
