51	int MappingInfoTy::associatePtr(void *HstPtrBegin, void *TgtPtrBegin,
52	                                int64_t Size) {
53	  HDTTMapAccessorTy HDTTMap = HostDataToTargetMap.getExclusiveAccessor();
54	
55	  // Check if entry exists
56	  auto It = HDTTMap->find(HstPtrBegin);
57	  if (It != HDTTMap->end()) {
58	    HostDataToTargetTy &HDTT = *It->HDTT;
59	    std::lock_guard<HostDataToTargetTy> LG(HDTT);
60	    // Mapping already exists
61	    bool IsValid = HDTT.HstPtrEnd == (uintptr_t)HstPtrBegin + Size &&
62	                   HDTT.TgtPtrBegin == (uintptr_t)TgtPtrBegin;
63	    if (IsValid) {
64	      ODBG(ODT_MappingExists) << "Attempt to re-associate the same device "
65	                              << "ptr+offset with the same "
66	                              << "host ptr, nothing to do";
67	      return OFFLOAD_SUCCESS;
68	    }
69	    REPORT() << "Not allowed to re-associate a different device ptr+offset "
70	             << "with the same host ptr";
71	    return OFFLOAD_FAIL;
72	  }
73	
74	  // Mapping does not exist, allocate it with refCount=INF
75	  const HostDataToTargetTy &NewEntry =
76	      *HDTTMap
77	           ->emplace(new HostDataToTargetTy(
78	               /*HstPtrBase=*/(uintptr_t)HstPtrBegin,
79	               /*HstPtrBegin=*/(uintptr_t)HstPtrBegin,
80	               /*HstPtrEnd=*/(uintptr_t)HstPtrBegin + Size,
81	               /*TgtAllocBegin=*/(uintptr_t)TgtPtrBegin,
82	               /*TgtPtrBegin=*/(uintptr_t)TgtPtrBegin,
83	               /*UseHoldRefCount=*/false, /*Name=*/nullptr,
84	               /*IsRefCountINF=*/true))
85	           .first->HDTT;
86	  ODBG(ODT_Mapping) << "Creating new map entry: HstBase="
87	                    << reinterpret_cast<void *>(NewEntry.HstPtrBase)
88	                    << ", HstBegin="
89	                    << reinterpret_cast<void *>(NewEntry.HstPtrBegin)
90	                    << ", HstEnd="
91	                    << reinterpret_cast<void *>(NewEntry.HstPtrEnd)
92	                    << ", TgtBegin="
93	                    << reinterpret_cast<void *>(NewEntry.TgtPtrBegin)
94	                    << ", DynRefCount=" << NewEntry.dynRefCountToStr()
95	                    << ", HoldRefCount=" << NewEntry.holdRefCountToStr();
96	  (void)NewEntry;
97	
98	  // Notify the plugin about the new mapping.
99	  return Device.notifyDataMapped(HstPtrBegin, Size);
100	}
