102	int MappingInfoTy::disassociatePtr(void *HstPtrBegin) {
103	  HDTTMapAccessorTy HDTTMap = HostDataToTargetMap.getExclusiveAccessor();
104	
105	  auto It = HDTTMap->find(HstPtrBegin);
106	  if (It == HDTTMap->end()) {
107	    REPORT() << "Association not found";
108	    return OFFLOAD_FAIL;
109	  }
110	  // Mapping exists
111	  HostDataToTargetTy &HDTT = *It->HDTT;
112	  std::lock_guard<HostDataToTargetTy> LG(HDTT);
113	
114	  if (HDTT.getHoldRefCount()) {
115	    // This is based on OpenACC 3.1, sec 3.2.33 "acc_unmap_data", L3656-3657:
116	    // "It is an error to call acc_unmap_data if the structured reference
117	    // count for the pointer is not zero."
118	    REPORT() << "Trying to disassociate a pointer with a non-zero "
119	             << "hold reference count";
120	    return OFFLOAD_FAIL;
121	  }
122	
123	  if (HDTT.isDynRefCountInf()) {
124	    ODBG(ODT_Mapping) << "Association found, removing it";
125	    void *Event = HDTT.getEvent();
126	    delete &HDTT;
127	    if (Event)
128	      Device.destroyEvent(Event);
129	    HDTTMap->erase(It);
130	    return Device.notifyDataUnmapped(HstPtrBegin);
131	  }
132	
133	  REPORT() << "Trying to disassociate a pointer which was not mapped via "
134	           << "omp_target_associate_ptr";
135	  return OFFLOAD_FAIL;
136	}
137	
138	LookupResult MappingInfoTy::lookupMapping(HDTTMapAccessorTy &HDTTMap,
139	                                          void *HstPtrBegin, int64_t Size,
140	                                          HostDataToTargetTy *OwnedTPR) {
141	
142	  uintptr_t HP = (uintptr_t)HstPtrBegin;
143	  LookupResult LR;
144	
145	  ODBG(ODT_Mapping) << "Looking up mapping(HstPtrBegin=" << HstPtrBegin
146	                    << ", Size=" << Size << ")...";
147	
148	  if (HDTTMap->empty())
149	    return LR;
150	
151	  // HDTTMap is std::set, ordered by HstPtrBegin.
152	  // Upper is the first element whose HstPtrBegin > HP.
153	  auto Upper = HDTTMap->upper_bound(HP);
154	
155	  if (Size == 0) {
156	    // HP satisfies
157	    //   std::prev(Upper)->HDTT.HstPtrBegin <= HP < Upper->HDTT.HstPtrBegin
158	    if (Upper != HDTTMap->begin()) {
159	      LR.TPR.setEntry(std::prev(Upper)->HDTT, OwnedTPR);
160	      // We know that HP >= LR.TPR.getEntry()->HstPtrBegin
161	      LR.Flags.IsContained = HP < LR.TPR.getEntry()->HstPtrEnd;
162	    }
163	
164	    if (!LR.Flags.IsContained && Upper != HDTTMap->end()) {
165	      LR.TPR.setEntry(Upper->HDTT, OwnedTPR);
166	      // This is a special case: HP is not really contained in the mapped
167	      // address range, but it's contained in the extended address range,
168	      // which suffices to get the mapping of the base pointer.
169	      // We know that HP < LR.TPR.getEntry()->HstPtrBegin
170	      LR.Flags.IsContained = HP >= LR.TPR.getEntry()->HstPtrBase;
171	    }
172	  } else {
173	    if (Upper != HDTTMap->begin()) {
174	      LR.TPR.setEntry(std::prev(Upper)->HDTT, OwnedTPR);
175	      // We know that HP >= LR.TPR.getEntry()->HstPtrBegin
176	      LR.Flags.IsContained = HP < LR.TPR.getEntry()->HstPtrEnd &&
177	                             (HP + Size) <= LR.TPR.getEntry()->HstPtrEnd;
178	      // Does it extend beyond the mapped address range?
179	      LR.Flags.ExtendsAfter = HP < LR.TPR.getEntry()->HstPtrEnd &&
180	                              (HP + Size) > LR.TPR.getEntry()->HstPtrEnd;
181	    }
182	
183	    if (!(LR.Flags.IsContained || LR.Flags.ExtendsAfter) &&
184	        Upper != HDTTMap->end()) {
185	      LR.TPR.setEntry(Upper->HDTT, OwnedTPR);
186	      // Does it extend into an already mapped address range?
187	      // We know that HP < LR.TPR.getEntry()->HstPtrBegin
188	      LR.Flags.ExtendsBefore = (HP + Size) > LR.TPR.getEntry()->HstPtrBegin;
189	      // Does it extend beyond the mapped address range?
190	      LR.Flags.ExtendsAfter = HP < LR.TPR.getEntry()->HstPtrEnd &&
191	                              (HP + Size) > LR.TPR.getEntry()->HstPtrEnd;
192	    }
193	
194	    if (LR.Flags.ExtendsBefore) {
195	      ODBG(ODT_Mapping) << "WARNING: Pointer is not mapped but section extends "
196	                        << "into already mapped data";
197	    }
198	    if (LR.Flags.ExtendsAfter) {
199	      ODBG(ODT_Mapping) << "WARNING: Pointer is already mapped but section "
200	                        << "extends beyond mapped region";
201	    }
202	  }
203	
204	  return LR;
205	}
206	
207	TargetPointerResultTy MappingInfoTy::getTargetPointer(
208	    HDTTMapAccessorTy &HDTTMap, void *HstPtrBegin, void *HstPtrBase,
209	    int64_t TgtPadding, int64_t Size, map_var_info_t HstPtrName, bool HasFlagTo,
210	    bool HasFlagAlways, bool IsImplicit, bool UpdateRefCount,
211	    bool HasCloseModifier, bool HasPresentModifier, bool HasHoldModifier,
212	    AsyncInfoTy &AsyncInfo, HostDataToTargetTy *OwnedTPR, bool ReleaseHDTTMap,
213	    StateInfoTy *StateInfo) {
214	
215	  LookupResult LR = lookupMapping(HDTTMap, HstPtrBegin, Size, OwnedTPR);
216	  LR.TPR.Flags.IsPresent = true;
217	
218	  // Release the mapping table lock only after the entry is locked by
219	  // attaching it to TPR. Once TPR is destroyed it will release the lock
220	  // on entry. If it is returned the lock will move to the returned object.
221	  // If LR.Entry is already owned/locked we avoid trying to lock it again.
222	
223	  // Check if the pointer is contained.
224	  // If a variable is mapped to the device manually by the user - which would
225	  // lead to the IsContained flag to be true - then we must ensure that the
226	  // device address is returned even under unified memory conditions.
227	  if (LR.Flags.IsContained ||
228	      ((LR.Flags.ExtendsBefore || LR.Flags.ExtendsAfter) && IsImplicit)) {
229	    const char *RefCountAction;
230	    if (UpdateRefCount) {
231	      // After this, reference count >= 1. If the reference count was 0 but the
232	      // entry was still there we can reuse the data on the device and avoid a
233	      // new submission.
234	      LR.TPR.getEntry()->incRefCount(HasHoldModifier);
235	      RefCountAction = " (incremented)";
236	    } else {
237	      // It might have been allocated with the parent, but it's still new.
238	      LR.TPR.Flags.IsNewEntry = LR.TPR.getEntry()->getTotalRefCount() == 1;
239	      RefCountAction = " (update suppressed)";
240	    }
241	    const char *DynRefCountAction = HasHoldModifier ? "" : RefCountAction;
242	    const char *HoldRefCountAction = HasHoldModifier ? RefCountAction : "";
243	    uintptr_t Ptr = LR.TPR.getEntry()->TgtPtrBegin +
244	                    ((uintptr_t)HstPtrBegin - LR.TPR.getEntry()->HstPtrBegin);
245	    INFO(OMP_INFOTYPE_MAPPING_EXISTS, Device.DeviceID,
246	         "Mapping exists%s with HstPtrBegin=" DPxMOD ", TgtPtrBegin=" DPxMOD
247	         ", Size=%" PRId64 ", DynRefCount=%s%s, HoldRefCount=%s%s, Name=%s\n",
248	         (IsImplicit ? " (implicit)" : ""), DPxPTR(HstPtrBegin), DPxPTR(Ptr),
249	         Size, LR.TPR.getEntry()->dynRefCountToStr().c_str(), DynRefCountAction,
250	         LR.TPR.getEntry()->holdRefCountToStr().c_str(), HoldRefCountAction,
251	         (HstPtrName) ? getNameFromMapping(HstPtrName).c_str() : "unknown");
252	    LR.TPR.TargetPointer = (void *)Ptr;
253	  } else if ((LR.Flags.ExtendsBefore || LR.Flags.ExtendsAfter) && !IsImplicit) {
254	    // Explicit extension of mapped data - not allowed.
255	    MESSAGE("explicit extension not allowed: host address specified is " DPxMOD
256	            " (%" PRId64
257	            " bytes), but device allocation maps to host at " DPxMOD
258	            " (%" PRId64 " bytes)",
259	            DPxPTR(HstPtrBegin), Size, DPxPTR(LR.TPR.getEntry()->HstPtrBegin),
260	            LR.TPR.getEntry()->HstPtrEnd - LR.TPR.getEntry()->HstPtrBegin);
261	    if (HasPresentModifier)
262	      MESSAGE("device mapping required by 'present' map type modifier does not "
263	              "exist for host address " DPxMOD " (%" PRId64 " bytes)",
264	              DPxPTR(HstPtrBegin), Size);
265	  } else if ((PM->getRequirements() & OMP_REQ_UNIFIED_SHARED_MEMORY &&
266	              !HasCloseModifier) ||
267	             (PM->getRequirements() & OMPX_REQ_AUTO_ZERO_COPY)) {
268	
269	    // If unified shared memory is active, implicitly mapped variables that are
270	    // not privatized use host address. Any explicitly mapped variables also use
271	    // host address where correctness is not impeded. In all other cases maps
272	    // are respected.
273	    // In addition to the mapping rules above, the close map modifier forces the
274	    // mapping of the variable to the device.
275	    if (Size) {
276	      INFO(OMP_INFOTYPE_MAPPING_CHANGED, Device.DeviceID,
277	           "Return HstPtrBegin " DPxMOD " Size=%" PRId64 " for unified shared "
278	           "memory\n",
279	           DPxPTR((uintptr_t)HstPtrBegin), Size);
280	      ODBG(ODT_Mapping) << "Return HstPtrBegin " << HstPtrBegin
281	                        << " Size=" << Size << " for unified shared memory";
282	      LR.TPR.Flags.IsPresent = false;
283	      LR.TPR.Flags.IsHostPointer = true;
284	      LR.TPR.TargetPointer = HstPtrBegin;
285	    }
286	  } else if (HasPresentModifier) {
287	    ODBG(ODT_Mapping) << "Mapping required by 'present' map type modifier does "
288	                      << "not exist for HstPtrBegin=" << HstPtrBegin
289	                      << ", Size=" << Size;
290	    MESSAGE("device mapping required by 'present' map type modifier does not "
291	            "exist for host address " DPxMOD " (%" PRId64 " bytes)",
292	            DPxPTR(HstPtrBegin), Size);
293	  } else if (Size) {
294	    // If it is not contained and Size > 0, we should create a new entry for it.
295	    LR.TPR.Flags.IsNewEntry = true;
296	    uintptr_t TgtAllocBegin =
297	        (uintptr_t)Device.allocData(TgtPadding + Size, HstPtrBegin);
298	    uintptr_t TgtPtrBegin = TgtAllocBegin + TgtPadding;
299	    // Release the mapping table lock only after the entry is locked by
300	    // attaching it to TPR.
301	    LR.TPR.setEntry(HDTTMap
302	                        ->emplace(new HostDataToTargetTy(
303	                            (uintptr_t)HstPtrBase, (uintptr_t)HstPtrBegin,
304	                            (uintptr_t)HstPtrBegin + Size, TgtAllocBegin,
305	                            TgtPtrBegin, HasHoldModifier, HstPtrName))
306	                        .first->HDTT);
307	    INFO(OMP_INFOTYPE_MAPPING_CHANGED, Device.DeviceID,
308	         "Creating new map entry with HstPtrBase=" DPxMOD
309	         ", HstPtrBegin=" DPxMOD ", TgtAllocBegin=" DPxMOD
310	         ", TgtPtrBegin=" DPxMOD
311	         ", Size=%ld, DynRefCount=%s, HoldRefCount=%s, Name=%s\n",
312	         DPxPTR(HstPtrBase), DPxPTR(HstPtrBegin), DPxPTR(TgtAllocBegin),
313	         DPxPTR(TgtPtrBegin), Size,
314	         LR.TPR.getEntry()->dynRefCountToStr().c_str(),
315	         LR.TPR.getEntry()->holdRefCountToStr().c_str(),
316	         (HstPtrName) ? getNameFromMapping(HstPtrName).c_str() : "unknown");
317	    LR.TPR.TargetPointer = (void *)TgtPtrBegin;
318	
319	    // Notify the plugin about the new mapping.
320	    if (Device.notifyDataMapped(HstPtrBegin, Size))
321	      return TargetPointerResultTy{};
322	  } else {
323	    // This entry is not present and we did not create a new entry for it.
324	    LR.TPR.Flags.IsPresent = false;
325	  }
326	
327	  // All mapping table modifications have been made. If the user requested it we
328	  // give up the lock.
329	  if (ReleaseHDTTMap)
330	    HDTTMap.destroy();
331	
332	  // Lambda to check if this pointer was newly allocated on the current region.
333	  // This is needed to handle cases when the TO entry is encountered after an
334	  // alloc entry for the same pointer. In such cases, the ref-count is already
335	  // non-zero when TO is encountered, but we still need to do a transfer. e.g.
336	  //
337	  // struct S {
338	  //   int *p;
339	  // };
340	  // #pragma omp declare mapper(id : S s) map(to: s.p, s.p[0 : 10])
341	  //
342	  // S s1;
343	  // ...
344	  // #pragma omp target map(alloc : s1.p[0 : 10]) map(mapper(id), to : s1)
345	  auto WasNewlyAllocatedForCurrentRegion = [&]() {
346	    if (!StateInfo)
347	      return false;
348	    bool WasNewlyAllocated =
349	        StateInfo->wasNewlyAllocated(HstPtrBegin).has_value();
350	    if (WasNewlyAllocated)
351	      ODBG(ODT_Mapping) << "HstPtrBegin " << HstPtrBegin
352	                        << " was newly allocated for the current region";
353	    return WasNewlyAllocated;
354	  };
355	
356	  // Even if this isn't a new entry, we still need to do a data-transfer if
357	  // the pointer was newly allocated on the current target region.
358	  if (LR.TPR.TargetPointer && !LR.TPR.Flags.IsHostPointer && HasFlagTo &&
359	      (LR.TPR.Flags.IsNewEntry || HasFlagAlways ||
360	       WasNewlyAllocatedForCurrentRegion()) &&
361	      Size != 0) {
362	
363	    // If we have something like:
364	    //   #pragma omp target map(to: s.myarr[0:10]) map(to: s.myarr[0:10])
365	    // then we see two "new" mappings of the struct member s.myarr here --
366	    // and both have the "IsNewEntry" flag set, so trigger the copy to device
367	    // below.  But, the shadow pointer is only initialised on the target for
368	    // the first copy, and the second copy clobbers it.  So, this condition
369	    // avoids the (second) copy here if we have already set shadow pointer info.
370	    auto FailOnPtrFound = [HstPtrBegin, Size](ShadowPtrInfoTy &SP) {
371	      if (SP.HstPtrAddr >= HstPtrBegin &&
372	          SP.HstPtrAddr < (void *)((char *)HstPtrBegin + Size))
373	        return OFFLOAD_FAIL;
374	      return OFFLOAD_SUCCESS;
375	    };
376	    if (LR.TPR.getEntry()->foreachShadowPointerInfo(FailOnPtrFound) ==
377	        OFFLOAD_FAIL) {
378	      ODBG(ODT_Mapping) << "Multiple new mappings of " << Size
379	                        << " bytes detected (hst:" << HstPtrBegin
380	                        << ") -> (tgt:" << LR.TPR.TargetPointer << ")";
381	      return std::move(LR.TPR);
382	    }
383	
384	    ODBG(ODT_Mapping) << "Moving " << Size << " bytes (hst:" << HstPtrBegin
385	                      << ") -> (tgt:" << LR.TPR.TargetPointer << ")";
386	
387	    int Ret = Device.submitData(LR.TPR.TargetPointer, HstPtrBegin, Size,
388	                                AsyncInfo, LR.TPR.getEntry());
389	    if (Ret != OFFLOAD_SUCCESS) {
390	      REPORT() << "Copying data to device failed.";
391	      // We will also return nullptr if the data movement fails because that
392	      // pointer points to a corrupted memory region so it doesn't make any
393	      // sense to continue to use it.
394	      LR.TPR.TargetPointer = nullptr;
395	    } else if (LR.TPR.getEntry()->addEventIfNecessary(Device, AsyncInfo) !=
396	               OFFLOAD_SUCCESS)
397	      return TargetPointerResultTy{};
398	  } else {
399	    // If not a host pointer and no present modifier, we need to wait for the
400	    // event if it exists.
401	    // Note: Entry might be nullptr because of zero length array section.
402	    if (LR.TPR.getEntry() && !LR.TPR.Flags.IsHostPointer &&
403	        !HasPresentModifier) {
404	      void *Event = LR.TPR.getEntry()->getEvent();
405	      if (Event) {
406	        int Ret = Device.waitEvent(Event, AsyncInfo);
407	        if (Ret != OFFLOAD_SUCCESS) {
408	          // If it fails to wait for the event, we need to return nullptr in
409	          // case of any data race.
410	          REPORT() << "Failed to wait for event " << Event << ".";
411	          return TargetPointerResultTy{};
412	        }
413	      }
414	    }
415	  }
416	
417	  return std::move(LR.TPR);
418	}
419	
420	TargetPointerResultTy MappingInfoTy::getTgtPtrBegin(
421	    void *HstPtrBegin, int64_t Size, bool UpdateRefCount, bool UseHoldRefCount,
422	    bool MustContain, bool ForceDelete, bool FromDataEnd) {
423	  HDTTMapAccessorTy HDTTMap = HostDataToTargetMap.getExclusiveAccessor();
424	
425	  LookupResult LR = lookupMapping(HDTTMap, HstPtrBegin, Size);
426	
427	  LR.TPR.Flags.IsPresent = true;
428	
429	  if (LR.Flags.IsContained ||
430	      (!MustContain && (LR.Flags.ExtendsBefore || LR.Flags.ExtendsAfter))) {
431	    LR.TPR.Flags.IsLast =
432	        LR.TPR.getEntry()->decShouldRemove(UseHoldRefCount, ForceDelete);
433	
434	    if (ForceDelete) {
435	      LR.TPR.getEntry()->resetRefCount(UseHoldRefCount);
436	      assert(LR.TPR.Flags.IsLast ==
437	                 LR.TPR.getEntry()->decShouldRemove(UseHoldRefCount) &&
438	             "expected correct IsLast prediction for reset");
439	    }
440	
441	    // Increment the number of threads that is using the entry on a
442	    // targetDataEnd, tracking the number of possible "deleters". A thread may
443	    // come to own the entry deletion even if it was not the last one querying
444	    // for it. Thus, we must track every query on targetDataEnds to ensure only
445	    // the last thread that holds a reference to an entry actually deletes it.
446	    if (FromDataEnd)
447	      LR.TPR.getEntry()->incDataEndThreadCount();
448	
449	    const char *RefCountAction;
450	    if (!UpdateRefCount) {
451	      RefCountAction = " (update suppressed)";
452	    } else if (LR.TPR.Flags.IsLast) {
453	      LR.TPR.getEntry()->decRefCount(UseHoldRefCount);
454	      assert(LR.TPR.getEntry()->getTotalRefCount() == 0 &&
455	             "Expected zero reference count when deletion is scheduled");
456	      if (ForceDelete)
457	        RefCountAction = " (reset, delayed deletion)";
458	      else
459	        RefCountAction = " (decremented, delayed deletion)";
460	    } else {
461	      LR.TPR.getEntry()->decRefCount(UseHoldRefCount);
462	      RefCountAction = " (decremented)";
463	    }
464	    const char *DynRefCountAction = UseHoldRefCount ? "" : RefCountAction;
465	    const char *HoldRefCountAction = UseHoldRefCount ? RefCountAction : "";
466	    uintptr_t TP = LR.TPR.getEntry()->TgtPtrBegin +
467	                   ((uintptr_t)HstPtrBegin - LR.TPR.getEntry()->HstPtrBegin);
468	    INFO(OMP_INFOTYPE_MAPPING_EXISTS, Device.DeviceID,
469	         "Mapping exists with HstPtrBegin=" DPxMOD ", TgtPtrBegin=" DPxMOD ", "
470	         "Size=%" PRId64 ", DynRefCount=%s%s, HoldRefCount=%s%s\n",
471	         DPxPTR(HstPtrBegin), DPxPTR(TP), Size,
472	         LR.TPR.getEntry()->dynRefCountToStr().c_str(), DynRefCountAction,
473	         LR.TPR.getEntry()->holdRefCountToStr().c_str(), HoldRefCountAction);
474	    LR.TPR.TargetPointer = (void *)TP;
475	  } else if (PM->getRequirements() & OMP_REQ_UNIFIED_SHARED_MEMORY ||
476	             PM->getRequirements() & OMPX_REQ_AUTO_ZERO_COPY) {
477	    // If the value isn't found in the mapping and unified shared memory
478	    // is on then it means we have stumbled upon a value which we need to
479	    // use directly from the host.
480	    ODBG(ODT_Mapping) << "Get HstPtrBegin " << HstPtrBegin << " Size=" << Size
481	                      << " for unified shared memory";
482	    LR.TPR.Flags.IsPresent = false;
483	    LR.TPR.Flags.IsHostPointer = true;
484	    LR.TPR.TargetPointer = HstPtrBegin;
485	  } else {
486	    // OpenMP Specification v5.2: if a matching list item is not found, the
487	    // pointer retains its original value as per firstprivate semantics.
488	    LR.TPR.Flags.IsPresent = false;
489	    LR.TPR.Flags.IsHostPointer = false;
490	    LR.TPR.TargetPointer = HstPtrBegin;
491	  }
492	
493	  return std::move(LR.TPR);
494	}
495	
496	// Return the target pointer begin (where the data will be moved).
497	void *MappingInfoTy::getTgtPtrBegin(HDTTMapAccessorTy &HDTTMap,
498	                                    void *HstPtrBegin, int64_t Size) {
499	  uintptr_t HP = (uintptr_t)HstPtrBegin;
500	  LookupResult LR = lookupMapping(HDTTMap, HstPtrBegin, Size);
501	  if (LR.Flags.IsContained || LR.Flags.ExtendsBefore || LR.Flags.ExtendsAfter) {
502	    uintptr_t TP =
503	        LR.TPR.getEntry()->TgtPtrBegin + (HP - LR.TPR.getEntry()->HstPtrBegin);
504	    return (void *)TP;
505	  }
506	
507	  return NULL;
508	}
509	
510	int MappingInfoTy::eraseMapEntry(HDTTMapAccessorTy &HDTTMap,
511	                                 HostDataToTargetTy *Entry, int64_t Size) {
512	  assert(Entry && "Trying to delete a null entry from the HDTT map.");
513	  assert(Entry->getTotalRefCount() == 0 &&
514	         Entry->getDataEndThreadCount() == 0 &&
515	         "Trying to delete entry that is in use or owned by another thread.");
516	
517	  INFO(OMP_INFOTYPE_MAPPING_CHANGED, Device.DeviceID,
518	       "Removing map entry with HstPtrBegin=" DPxMOD ", TgtPtrBegin=" DPxMOD
519	       ", Size=%" PRId64 ", Name=%s\n",
520	       DPxPTR(Entry->HstPtrBegin), DPxPTR(Entry->TgtPtrBegin), Size,
521	       (Entry->HstPtrName) ? getNameFromMapping(Entry->HstPtrName).c_str()
522	                           : "unknown");
523	
524	  if (HDTTMap->erase(Entry) == 0) {
525	    REPORT() << "Trying to remove a non-existent map entry";
526	    return OFFLOAD_FAIL;
527	  }
528	
529	  return OFFLOAD_SUCCESS;
530	}
531	
532	int MappingInfoTy::deallocTgtPtrAndEntry(HostDataToTargetTy *Entry,
533	                                         int64_t Size) {
534	  assert(Entry && "Trying to deallocate a null entry.");
535	
536	  ODBG(ODT_Mapping) << "Deleting tgt data "
537	                    << reinterpret_cast<void *>(Entry->TgtPtrBegin)
538	                    << " of size " << Size << " by freeing allocation "
539	                    << "starting at "
540	                    << reinterpret_cast<void *>(Entry->TgtAllocBegin);
541	
542	  void *Event = Entry->getEvent();
543	  if (Event && Device.destroyEvent(Event) != OFFLOAD_SUCCESS) {
544	    REPORT() << "Failed to destroy event " << Event;
545	    return OFFLOAD_FAIL;
546	  }
547	
548	  int Ret = Device.deleteData((void *)Entry->TgtAllocBegin);
549	
550	  // Notify the plugin about the unmapped memory.
551	  Ret |= Device.notifyDataUnmapped((void *)Entry->HstPtrBegin);
552	
553	  delete Entry;
554	
555	  return Ret;
556	}
557	
558	static void printCopyInfoImpl(int DeviceId, bool H2D, void *SrcPtrBegin,
559	                              void *DstPtrBegin, int64_t Size,
560	                              HostDataToTargetTy *HT) {
561	
562	  INFO(OMP_INFOTYPE_DATA_TRANSFER, DeviceId,
563	       "Copying data from %s to %s, %sPtr=" DPxMOD ", %sPtr=" DPxMOD
564	       ", Size=%" PRId64 ", Name=%s\n",
565	       H2D ? "host" : "device", H2D ? "device" : "host", H2D ? "Hst" : "Tgt",
566	       DPxPTR(H2D ? SrcPtrBegin : DstPtrBegin), H2D ? "Tgt" : "Hst",
567	       DPxPTR(H2D ? DstPtrBegin : SrcPtrBegin), Size,
568	       (HT && HT->HstPtrName) ? getNameFromMapping(HT->HstPtrName).c_str()
569	                              : "unknown");
570	}
571	
572	void MappingInfoTy::printCopyInfo(
573	    void *TgtPtrBegin, void *HstPtrBegin, int64_t Size, bool H2D,
574	    HostDataToTargetTy *Entry, MappingInfoTy::HDTTMapAccessorTy *HDTTMapPtr) {
575	  auto HDTTMap =
576	      HostDataToTargetMap.getExclusiveAccessor(!!Entry || !!HDTTMapPtr);
577	  LookupResult LR;
578	  if (!Entry) {
579	    LR = lookupMapping(HDTTMapPtr ? *HDTTMapPtr : HDTTMap, HstPtrBegin, Size);
580	    Entry = LR.TPR.getEntry();
581	  }
582	  printCopyInfoImpl(Device.DeviceID, H2D, HstPtrBegin, TgtPtrBegin, Size,
583	                    Entry);
584	}
